func federatedArtifactLastChange(files Files, source Store, identity ArtifactRef) string {
	var path string
	if identity.Kind == "spec" {
		sp, err := source.GetSpec(identity.Slug)
		if err != nil {
			return ""
		}
		path = sp.Path
	} else {
		rm, err := source.GetRoadmap(identity.Slug)
		if err != nil {
			return ""
		}
		path = rm.Path
	}
	rel, err := filepath.Rel(source.Root, path)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return ""
